#!/usr/bin/env python3
import base64, zlib, pathlib, hashlib
payload = ""
content = zlib.decompress(base64.b64decode(payload))
expected = "d88894187e4b719b0d317f7d1735f79b8870045f6002da44008fc2edec8b58e7"
actual = hashlib.sha256(content).hexdigest()
if actual != expected:
    raise SystemExit(f"payload checksum mismatch: {actual}")
path = pathlib.Path("data/pervenstvo-rossii-yuniory-2025.json")
path.write_bytes(content)
print(f"wrote {path}: {len(content)} bytes sha256={actual}")
